.ds-primary-action { display: inline-flex; align-items: center; justify-content: center; gap: .62rem; min-height: 2.75rem; font-weight: 740; border: 1px solid transparent; border-radius: 2rem; transition: background-color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)), color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)), border-color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)); }
