.ds-primary-action:focus-visible { outline: 3px solid var(--rose-ink, #98394d); outline-offset: 4px; }
.ds-primary-action { font-family: var(--text, 'DM Sans Variable', Arial, sans-serif); text-decoration: none; cursor: pointer; }
