.ds-secondary-action { padding: .55rem .95rem; border-color: var(--berry, #63273f); color: var(--berry, #63273f); background: transparent; }
.ds-secondary-action:hover { color: var(--paper, #fffaf4); background: var(--berry, #63273f); }
.ds-secondary-action:focus-visible { outline: 3px solid var(--rose-ink, #98394d); outline-offset: 4px; }
.ds-secondary-action { font-family: var(--text, 'DM Sans Variable', Arial, sans-serif); text-decoration: none; cursor: pointer; }
