.ds-contact-pill { display: inline-flex; align-items: center; justify-content: center; gap: .62rem; min-height: 2.75rem; font-weight: 740; border: 1px solid transparent; border-radius: 2rem; transition: background-color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)), color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)), border-color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)); }
.ds-contact-pill { padding: .55rem .85rem; border-color: #c9a5ae; white-space: nowrap; }
.ds-contact-pill:hover { background: var(--berry, #63273f); color: var(--paper, #fffaf4); border-color: var(--berry, #63273f); }
.ds-contact-pill:focus-visible { outline: 3px solid var(--rose-ink, #98394d); outline-offset: 4px; }
.ds-contact-pill { font-family: var(--text, 'DM Sans Variable', Arial, sans-serif); text-decoration: none; cursor: pointer; }
.ds-contact-pill { font-size: .91rem; color: var(--berry, #63273f); }
.ds-contact-pill:hover { background: var(--berry, #63273f); color: var(--paper, #fffaf4); border-color: var(--berry, #63273f); }
@media (prefers-reduced-motion: reduce) { .ds-contact-pill { transition-duration: 0ms; } }

.ds-site-footer { position: relative; background: var(--plum, #351926); color: var(--paper, #fffaf4); }
.ds-site-footer :focus-visible { outline-color: #f1b1bc; }
.ds-site-footer { padding: 1rem; }
.ds-directions-link { display: inline-flex; align-items: center; justify-content: center; gap: .62rem; min-height: 2.75rem; font-weight: 740; border: 1px solid transparent; border-radius: 2rem; transition: background-color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)), color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)), border-color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)); }
.ds-directions-link { padding: .55rem .88rem; color: var(--plum, #351926); background: var(--sky, #deebef); }
.ds-directions-link:hover { background: #f2cbd0; }
.ds-directions-link:focus-visible { outline: 3px solid var(--rose-ink, #98394d); outline-offset: 4px; }
.ds-directions-link { font-family: var(--text, 'DM Sans Variable', Arial, sans-serif); text-decoration: none; cursor: pointer; }
@media (prefers-reduced-motion: reduce) { .ds-directions-link { transition-duration: 0ms; } }

.ds-category-list { display: flex; flex-wrap: wrap; gap: .47rem; }
.ds-category-list button { padding: .48rem .82rem; min-height: 2.75rem; color: var(--berry, #63273f); background: transparent; border: 1px solid var(--line, #ddc6c2); border-radius: 2rem; font-size: .88rem; font-weight: 690; transition: background-color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)), color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)), border-color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)); }
.ds-category-list button:hover { border-color: var(--berry, #63273f); }
.ds-category-list button[aria-pressed="true"] { border-color: var(--berry, #63273f); background: var(--berry, #63273f); color: var(--paper, #fffaf4); }
.ds-category-list button { font: 690 .88rem/1.55 var(--text, 'DM Sans Variable', Arial, sans-serif); cursor: pointer; }
.ds-category-list button:focus-visible { outline: 3px solid var(--rose-ink, #98394d); outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-category-list button { transition-duration: 0ms; } }

.ds-search-field { display: flex; align-items: center; gap: .55rem; flex: 0 1 17.5rem; min-width: 0; min-height: 2.75rem; padding-inline: .85rem; background: var(--paper, #fffaf4); color: var(--berry, #63273f); border: 1px solid var(--line, #ddc6c2); border-radius: 2rem; }
.ds-search-field:focus-within { border-color: var(--rose-ink, #98394d); box-shadow: 0 0 0 1px var(--rose-ink, #98394d); }
.ds-search-field input { padding: .45rem 0; min-width: 0; width: 100%; background: transparent; border: 0; color: var(--ink, #36202c); font-size: 1rem; outline: none; }
.ds-search-field input::placeholder { color: var(--muted, #69505a); }
.ds-search-field svg { flex: none; }
.ds-search-field input { font-family: var(--text, 'DM Sans Variable', Arial, sans-serif); line-height: 1.55; }

.ds-product-link { display: block; height: 100%; border-radius: .68rem .68rem .26rem .26rem; }
.ds-product-photo { aspect-ratio: 1.05; overflow: hidden; background: var(--blush, #f6ddd9); position: relative; border-radius: .68rem; }
.ds-product-photo img { width: 100%; height: 100%; object-fit: cover; transition: transform var(--image-time, 540ms) var(--settle, cubic-bezier(.16, 1, .3, 1)); }
.ds-product-details { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: .4rem; padding: .68rem .03rem .75rem; border-bottom: 1px solid var(--line, #ddc6c2); }
.ds-product-details h3 { margin: 0 0 .25rem; font-size: 1rem; line-height: 1.28; font-weight: 720; overflow-wrap: anywhere; }
.ds-product-prices { display: flex; align-items: baseline; flex-wrap: wrap; gap: .1rem .46rem; color: var(--berry, #63273f); font-variant-numeric: tabular-nums; }
.ds-product-prices strong { font-size: 1.02rem; font-weight: 760; }
.ds-product-arrow { color: var(--berry, #63273f); display: inline-flex; padding: .08rem .06rem; transition: transform var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)); }
.ds-product-link { text-decoration: none; color: var(--ink, #36202c); font: 1rem/1.55 var(--text, 'DM Sans Variable', Arial, sans-serif); }
.ds-product-photo img { display: block; }
.ds-sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.ds-product-link:focus-visible { outline: 3px solid var(--rose-ink, #98394d); outline-offset: 4px; }
@media (hover: hover) { .ds-product-link:hover img { transform: scale(1.06); } .ds-product-link:hover .ds-product-arrow { transform: translate(3px, -3px); } .ds-product-link:hover h3 { text-decoration: underline; text-underline-offset: .21em; } }
@media (prefers-reduced-motion: reduce) { .ds-product-photo img, .ds-product-arrow { transition-duration: 0ms; } }

.ds-site-header { background: var(--paper, #fffaf4); border-bottom: 1px solid #6235461f; }
.ds-header-inner { min-height: 5.15rem; display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.ds-brand, .ds-header-inner nav { display: flex; align-items: center; }
.ds-brand { gap: .62rem; flex: none; }
.ds-brand img { width: 3rem; height: 3rem; border-radius: .45rem; }
.ds-brand strong, .ds-brand small { display: block; }
.ds-brand strong { font: 640 1.65rem/.95 var(--display, 'Fraunces Variable', Georgia, serif); letter-spacing: -.025em; color: var(--berry, #63273f); }
.ds-brand small { margin-top: .26rem; font-size: .7rem; font-weight: 650; color: var(--muted, #69505a); white-space: nowrap; }
.ds-header-inner nav { gap: 1.55rem; font-weight: 700; font-size: .91rem; color: var(--berry, #63273f); }
.ds-nav-link { display: inline-flex; align-items: center; min-height: 44px; white-space: nowrap; }
.ds-nav-link:hover { text-decoration: underline; text-underline-offset: .26em; }
.ds-contact-pill { display: inline-flex; align-items: center; justify-content: center; gap: .62rem; min-height: 2.75rem; font-weight: 740; border: 1px solid transparent; border-radius: 2rem; transition: background-color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)), color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)), border-color var(--quick, 220ms) var(--settle, cubic-bezier(.16, 1, .3, 1)); }
.ds-contact-pill { padding: .55rem .85rem; border-color: #c9a5ae; white-space: nowrap; }
.ds-contact-pill:hover { background: var(--berry, #63273f); color: var(--paper, #fffaf4); border-color: var(--berry, #63273f); }
.ds-contact-pill:focus-visible { outline: 3px solid var(--rose-ink, #98394d); outline-offset: 4px; }
.ds-contact-pill { font-family: var(--text, 'DM Sans Variable', Arial, sans-serif); text-decoration: none; cursor: pointer; }
.ds-site-header { font: 1rem/1.55 var(--text, 'DM Sans Variable', Arial, sans-serif); color: var(--ink, #36202c); }
.ds-site-header a { color: inherit; text-decoration: none; }
.ds-site-header .ds-contact-pill:hover { color: var(--paper, #fffaf4); }
.ds-site-header a:focus-visible { outline: 3px solid var(--rose-ink, #98394d); outline-offset: 4px; }
@media (max-width: 799px) { .ds-header-inner { min-height: 4.45rem; gap: .6rem; } .ds-brand { gap: .46rem; } .ds-brand img { width: 2.42rem; height: 2.42rem; } .ds-brand strong { font-size: 1.4rem; } .ds-brand small { font-size: .64rem; } .ds-header-inner nav { gap: .68rem; font-size: .79rem; } .ds-nav-catalog { display: none; } .ds-contact-pill { padding: .4rem .63rem; gap: .38rem; } .ds-contact-pill svg { width: .91rem; height: .91rem; } }
@media (prefers-reduced-motion: reduce) { .ds-contact-pill { transition-duration: 0ms; } }

.ds-collection-link { position: relative; display: flex; min-width: 0; height: clamp(8.3rem, 15vw, 13.5rem); align-items: end; isolation: isolate; overflow: hidden; border-radius: .65rem; color: #fffaf4; background: var(--plum, #351926); }
.ds-collection-link img { position: absolute; z-index: -2; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: 50% 49%; }
.ds-collection-link::after { content: ''; position: absolute; z-index: -1; inset: 0; background: linear-gradient(5deg, #2b1422ee 0%, #2b1422a5 26%, #2b142200 75%); }
.ds-collection-link span { margin: .85rem; padding: .25rem .5rem; display: flex; align-items: center; gap: .6rem; border-radius: .24rem; background: #351926; font-weight: 700; line-height: 1.2; }
.ds-collection-link img, .ds-collection-link svg { transition: transform var(--image-time, 540ms) var(--settle, cubic-bezier(.16, 1, .3, 1)); }
.ds-collection-link { font-family: var(--text, 'DM Sans Variable', Arial, sans-serif); text-decoration: none; }
.ds-collection-link:focus-visible { outline: 3px solid var(--rose-ink, #98394d); outline-offset: 4px; }
@media (hover: hover) { .ds-collection-link:hover img { transform: scale(1.06); } .ds-collection-link:hover svg { transform: translate(2px, -2px); } }
@media (max-width: 499px) { .ds-collection-link { height: 7.75rem; } .ds-collection-link span { margin: .43rem; padding: .2rem .3rem; font-size: .82rem; } .ds-collection-link svg { display: none; } }
@media (prefers-reduced-motion: reduce) { .ds-collection-link img, .ds-collection-link svg { transition-duration: 0ms; } }

.ds-hero { overflow: clip; isolation: isolate; position: relative; background: linear-gradient(117deg, #faeee3 5%, #f7e1dc 50%, #edbdbe 100%); border-bottom: 1px solid #bd78882e; }
.ds-hero-deck { position: relative; isolation: isolate; width: 100%; aspect-ratio: 1.15; }
.ds-hero-deck::before, .ds-hero-deck::after { content: ''; position: absolute; pointer-events: none; }
.ds-hero-deck::before { inset: 4% 1% 9% 24%; background: #d98694; border-radius: 37% .85rem .85rem .85rem; transform: rotate(10deg); box-shadow: 0 22px 52px #7e344127; }
.ds-hero-deck::after { width: 48%; aspect-ratio: 1; inset: 6% auto auto 1%; border-radius: 50%; border: 1px solid #a7586870; transform: rotate(-18deg) scaleY(1.16); }
.ds-hero-photo { position: absolute; z-index: 1; overflow: hidden; background: var(--blush, #f6ddd9); transform: rotate(var(--tilt, -10deg)); border: .48rem solid var(--paper, #fffaf4); box-shadow: 0 14px 40px #57283b31; }
.ds-hero-photo img { width: 100%; height: 100%; object-fit: cover; }
.ds-hero-main { --tilt: 4deg; inset: 0 7% 5% 17%; border-radius: 29% .72rem .72rem .72rem; }
.ds-hero-main img { object-position: 51% 50%; }
.ds-hero-accent { --tilt: -10deg; z-index: 2; width: 32%; aspect-ratio: .93; inset: auto auto -1% 1%; border-width: .4rem .4rem .95rem; border-radius: .25rem; }
.ds-hero-accent img { object-position: 52% 46%; }
.ds-hero { padding: 1rem; }
.ds-hero-photo, .ds-hero-photo img { box-sizing: border-box; }
.ds-hero-photo img { display: block; }
@media (max-width: 799px) { .ds-hero-deck { width: min(100%, 32rem); margin-inline: auto; aspect-ratio: 1.27; } .ds-hero-photo { border-width: .34rem; } .ds-hero-accent { border-width: .29rem .29rem .67rem; } }
